 copy:'M8 8h13v13H8z M16 8V3H3v13h5',trash:'M3 6h18 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',
 plus:'M12 5v14 M5 12h14',external:'M14 3h7v7 M21 3 11 13 M10 3H3v18h18v-7',
 settings:'m12 3 2 3 3-1 2 3-2 3 2 3-2 3-3-1-2 3-3-1-1-3-3-1v-4l3-1 1-3 3-1z M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0z',
 check:'m5 12 4 4L19 6',bulb:'M8 17c0-4-3-4-3-9a7 7 0 1 1 14 0c0 5-3 5-3 9H8z M8 21h8 M9 17v4 M15 17v4',
 list:'M9 5h12 M9 12h12 M9 19h12 M3 5h.1 M3 12h.1 M3 19h.1',
